import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let h = 1.5 + 0.5
    if h == 2.0 { io.println("fadd-ok") } else { io.println("fadd-bad") }
    let q = 7.0 / 2.0
    if q == 3.5 { io.println("fdiv-ok") } else { io.println("fdiv-bad") }
    let m = 7.0 % 2.0
    if m == 1.0 { io.println("fmod-ok") } else { io.println("fmod-bad") }
    let nf = -1.5
    if nf == 0.0 - 1.5 { io.println("fneg-ok") } else { io.println("fneg-bad") }
    return Ok(())
}
